     },
     {
      "var": "solid waste batches",
      "coef": -2.0
     }
    ],
    "sense": "==",
    "rhs": 0.0
   },
   {
    "name": "solid storage limit",
    "terms": [
     {
      "var": "solid waste batches",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 10.0
   }
  ]
 },
 "facts": {
